import {ArenaSoundEffects,ARENA_SOUND_FILES} from '/src/js/toy-room/ArenaSoundEffects.js';
import {sampleArenaPlayerAnimation} from '/src/js/toy-room/ArenaPlayerAnimation.js';
import {beginArenaSpecial} from '/src/js/toy-room/ArenaSpecialAttack.js';
const wait=ms=>new Promise(r=>setTimeout(r,ms));
const check=(v,msg)=>{if(!v)throw Error(msg);};
const attacks={train:['Steam Blast','Front Charge'],robot:['Laser Beam','Rocket Punch'],dinosaur:['Bite','Rush'],bear:['Bear Hug','Belly Charge','Toy Leap']};
function metrics(buffer,from=0,duration=buffer.duration){
 const start=Math.floor(from*buffer.sampleRate),end=Math.min(buffer.length,Math.floor((from+duration)*buffer.sampleRate)),hop=Math.round(buffer.sampleRate*.01);
 let peak=0,sum=0,n=0,first=null,last=null,peakAt=0;const envelope=[];
 for(let i=start;i<end;i+=hop){let energy=0,nn=0,p=0;for(let c=0;c<buffer.numberOfChannels;c++){const d=buffer.getChannelData(c);for(let j=i;j<Math.min(end,i+hop);j++){const a=Math.abs(d[j]);if(a>peak){peak=a;peakAt=(j-start)/buffer.sampleRate;}p=Math.max(p,a);energy+=a*a;nn++;}}const rms=Math.sqrt(energy/nn);envelope.push(rms);sum+=energy;n+=nn;if(p>.025){first??=(i-start)/buffer.sampleRate;last=(i-start)/buffer.sampleRate;}}
 const maxRms=Math.max(...envelope);const strong=envelope.findIndex(v=>v>=maxRms*.5);
 return {pico:peak,rms:Math.sqrt(sum/n),primeiroSinalMs:first===null?null:first*1000,ultimoSinalMs:last===null?null:last*1000,picoMs:peakAt*1000,energiaForteMs:strong<0?null:strong*10,envelope};
}
export async function run(){
 const game=window.game;check(game,'Jogo disponível');await game.assetsReady;
 const media=[];const OriginalAudio=window.Audio;
 window.Audio=function(...args){const a=new OriginalAudio(...args);media.push(a);return a;};
 const eventos=[],samples=new Map(),batidas=[],capturas=[],frames=[];let stage='preparo',battle,room,arena,origin;
 const originalPlay=ArenaSoundEffects.prototype.play;
 ArenaSoundEffects.prototype.play=function(ctx,dest,event){
  const p=ARENA_SOUND_FILES[event];if(p&&this.buffers.has(p.file))samples.set(p.file,this.buffers.get(p.file));
  const s=battle?.state;
  const entry={etapa:stage,tempo:performance.now()/1000,audioTime:ctx.currentTime,event,quadro:s?.elapsed,ator:s?.enemy?.actor,estadoInimigo:s?.enemy?.state,idadeInimigo:s?.enemy?.elapsed,ataqueInimigo:s?.enemy?.attack,idadeEspada:s?.playerAnimation?.attackAge,idadeEspecial:s?.specialAttack?.elapsed,perfil:p??null};
  eventos.push(entry);const ret=originalPlay.call(this,ctx,dest,event);entry.amostra=Boolean(p&&ret);return ret;
 };
 const oldBeat=game.audio.system.playArenaMusicBeat;
 game.audio.system.playArenaMusicBeat=function(beat){batidas.push({tempo:performance.now()/1000,beat,etapa:stage});return oldBeat(beat);};
 game.startDebugPhase('arena','NORMAL');room=game.state.toyRoomInstance.instance;arena=room.arena;battle=room.battle;
 await Promise.all([battle.readyPromise,arena.readyPromise]);
 const ctx=game.audio.getAudioContext();await ctx.resume();
 const fx=new ArenaSoundEffects();await fx.preload(ctx);for(const [f,b]of fx.buffers)samples.set(f,b);
 document.getElementById('start-overlay').classList.add('hidden');
 const analyser=ctx.createAnalyser();analyser.fftSize=2048;const waveform=new Float32Array(2048);let mixCount=0,mixPeak=0,mixSquares=0,mixAbove=0;
 // Observa a saída dos efeitos sem alterar o caminho de áudio original.
 const oldConnect=AudioNode.prototype.connect;
 AudioNode.prototype.connect=function(target,...rest){const r=oldConnect.call(this,target,...rest);if(this.context===ctx&&target===ctx.destination)oldConnect.call(this,analyser);return r;};
 const music=media.find(a=>decodeURIComponent(a.src).includes('Circular Dissonance'));
 if(music){const src=ctx.createMediaElementSource(music);src.connect(ctx.destination);}
 function shot(nome){if(!capturas.some(s=>s.nome===nome))capturas.push({nome,data:document.getElementById('gameCanvas').toDataURL('image/png')});}
 const seen=new Map(),cycles=new Map();let lastActor=null,actorStart=performance.now(),firstDamage=false,finished=false;
 const originalBegin=battle.beginEnemyAttack.bind(battle);
 battle.beginEnemyAttack=function(attack){const actor=this.state.enemy.actor;seen.set(actor,new Set([...(seen.get(actor)??[]),attack]));cycles.set(actor,(cycles.get(actor)??0)+1);return originalBegin(attack);};
 stage='batalha-completa';origin=performance.now();
 const result=await new Promise((resolve,reject)=>{
 let previous=performance.now();
 function monitor(now){try{
 const s=battle.state;
 if(!s){reject(Error('Estado de batalha ausente'));return;}
 if(now-origin>210000){reject(Error('Prazo da batalha excedido: '+JSON.stringify({actor:s.enemy.actor,state:s.enemy.state,hp:s.enemy.hp,seen:[...(seen.get(s.enemy.actor)??[])]})));return;}
 if(arena.state.status==='RETURNING'||s.mode==='VICTORY'){finished=true;game.setPaused(true);resolve({resultado:s.mode,historico:JSON.parse(JSON.stringify(s.history)),duracaoReal:(now-origin)/1000,vida:s.player.hp});return;}
 const e=s.enemy,actor=e.actor;
 if(lastActor!==actor){lastActor=actor;actorStart=now;console.log('AUDITORIA adversário '+actor+' em '+((now-origin)/1000).toFixed(1)+' s');}
 const side=Math.sign(e.x-room.player.x)||1,dist=Math.abs(e.x-room.player.x),range=battle.getSwordRange(actor);
 const observed=(seen.get(actor)?.size??0)>=attacks[actor].length||(cycles.get(actor)??0)>=5;
 room.keysDown={};
 const key=x=>{if(x<0)room.keysDown.KeyA=true;if(x>0)room.keysDown.KeyD=true;};
 if(!s.transition&&arena.state.status==='COMBAT'){
  if(e.state==='ATTACK'&&e.elapsed<(e.attack==='Toy Leap'?96:battle.tuning.windup+battle.tuning.active)){
   const damageTest=actor==='train'&&!firstDamage&&s.player.hp===3;
   if(!damageTest)key(-side);
   if(damageTest&&e.landed)firstDamage=true;
  }else if(dist>range-12)key(side);
  if(actor==='bear'&&observed&&!s.specialUsed&&s.attackTime<=0&&s.playerHitTime<=0){beginArenaSpecial(battle);shot('especial-inicio');}
  else if(observed&&s.cooldown<=0&&dist<range-3&&e.hp>0&&!battle.enemyGuarding()&&e.state!=='ENRAGE'&&e.state!=='DEATH')battle.attack();
 }
 if(e.state==='ATTACK'&&e.elapsed>=54&&e.elapsed<57)shot(actor+'-ativo');
 if(s.specialAttack?.elapsed>=94&&s.specialAttack.elapsed<98)shot('especial-raio');
 if(s.impact?.target==='enemy')shot(actor+'-impacto-espada');
 if(frames.length===0||now-previous>=40){const a=sampleArenaPlayerAnimation(s,room.player);frames.push({t:(now-origin)/1000,quadro:s.elapsed,ator:actor,estado:e.state,idade:e.elapsed,ataque:e.attack,espada:s.attackTime,idadeEspada:s.playerAnimation?.attackAge,pose:a.pose,arco:a.slash?.alpha??0,pausa:s.hitPause,especial:s.specialAttack?.elapsed??null,musica:music?.currentTime,volumeMusica:music?.volume});previous=now;}
 analyser.getFloatTimeDomainData(waveform);for(const v of waveform){mixPeak=Math.max(mixPeak,Math.abs(v));mixSquares+=v*v;mixCount++;if(Math.abs(v)>=1)mixAbove++;}
 requestAnimationFrame(monitor);
 }catch(err){reject(err);}}
 requestAnimationFrame(monitor);
 });
 console.log('AUDITORIA batalha concluída em '+result.duracaoReal.toFixed(1)+' s');
 // Ensaios controlados adicionais usam as mesmas animações, física e efeitos da arena.
 // O avanço manual abaixo é exclusivo da auditoria; não representa uma segunda partida humana.
 const diagnosticos=[];stage='ensaio-ataques';
 game.audio.resumeMusic();await ctx.resume();
 for(const [actor,list]of Object.entries(attacks))for(const attack of list){
  battle.state.index=Object.keys(attacks).indexOf(actor);battle.spawn();
  const s=battle.state;s.mode='BATTLE';s.transition=null;s.player.hp=3;s.immunity=0;s.hitPause=0;s.attackTime=0;s.playerHitTime=0;s.jump=0;s.jumpVelocity=0;s.specialAttack=null;
  room.clearInput();room.player.x=650;s.enemy.x=650+battle.getEnemyCollisionDistance(actor)+2;s.enemy.facing=-1;
  const eventIndex=eventos.length;const start=performance.now();battle.beginEnemyAttack(attack);let firstActive=null,firstHit=null,stop=attack==='Toy Leap'?110:85;
  for(let i=0;i<stop;i++){battle.update(1);const e=s.enemy;if(firstActive===null&&e.elapsed>=(attack==='Toy Leap'?84:battle.tuning.windup))firstActive={quadro:i+1,ms:performance.now()-start};if(firstHit===null&&e.landed)firstHit={quadro:i+1,ms:performance.now()-start};battle.render();await wait(1000/60);}
  diagnosticos.push({actor,attack,primeiroAtivo:firstActive,primeiroContato:firstHit,eventos:eventos.slice(eventIndex).filter(e=>e.event!=='player_walk'&&!e.event.endsWith('_walk'))});
 }
 stage='analise-amostras';game.audio.stopAllAudio();
 const amostras=[];
 for(const [event,p]of Object.entries(ARENA_SOUND_FILES)){const b=samples.get(p.file),m=metrics(b,p.offset,Math.min(p.duration,b.duration-p.offset));amostras.push({event,arquivo:p.file,duracaoOriginal:b.duration,duracaoTrecho:p.duration,offset:p.offset,volume:p.volume,...m,envelope:undefined,picoSaida:m.pico*p.volume,rmsSaida:m.rms*p.volume});}
 const trackBuffer=await ctx.decodeAudioData(await(await fetch('/assets/audio/Circular%20Dissonance%20(1).mp3')).arrayBuffer());
 const trackMetrics=metrics(trackBuffer);const env=trackMetrics.envelope;
 const correlation=[];for(let lag=30;lag<=100;lag++){let corr=0;for(let i=lag;i<env.length;i++){const a=Math.max(0,env[i]-env[i-1]);const b=Math.max(0,env[i-lag]-(env[i-lag-1]??0));corr+=a*b;}correlation.push({lag,bpm:6000/lag,score:corr});}correlation.sort((a,b)=>b.score-a.score);
 const trilha={arquivo:'Circular Dissonance (1).mp3',duracao:trackBuffer.duration,volumeArena:.58*1.4,pico:trackMetrics.pico,rms:trackMetrics.rms,picoSaida:trackMetrics.pico*.58*1.4,rmsSaida:trackMetrics.rms*.58*1.4,primeiroSinalMs:trackMetrics.primeiroSinalMs,ultimoSinalMs:trackMetrics.ultimoSinalMs,bpmCandidatos:correlation.slice(0,8),percussaoBpm:150,batidas:batidas.filter(b=>b.etapa==='batalha-completa').length,elemento:music?{src:music.src,paused:music.paused,volume:music.volume,tempo:music.currentTime}:null};
 const defeated=result.historico.filter(e=>e.event==='DEFEATED').map(e=>e.enemy);
 const latency={sampleRate:ctx.sampleRate,baseLatency:ctx.baseLatency,outputLatency:ctx.outputLatency,estado:ctx.state,observacao:'Chrome headless com saída silenciada; medição técnica, sem escuta humana ou latência de alto-falante físico.'};
 ArenaSoundEffects.prototype.play=originalPlay;AudioNode.prototype.connect=oldConnect;window.Audio=OriginalAudio;
 return {resumo:{resultado:result.resultado,derrotados:defeated,duracaoReal:result.duracaoReal,vidaFinal:result.vida,ataquesNaturais:Object.fromEntries([...seen].map(([k,v])=>[k,[...v]])),eventos:eventos.filter(e=>e.etapa==='batalha-completa').length,observacao:'Partida contínua NORMAL por bot com movimento/defesa/espada/especial; sem editar HP, posições ou relógios durante a partida. Ensaios de nove ataques separados usam estados preparados.'},latencia:latency,mixagem:{pico:mixPeak,rms:Math.sqrt(mixSquares/mixCount),amostrasAcimaDe1:mixAbove,amostras:mixCount,observacao:'Analisador observa conexões efetuadas depois de instalado; trilha inclusa, ganho mestre preexistente não capturado. Não é medição do mix completo dos efeitos.'},amostras,trilha,diagnosticos,eventos,frames,batidas,historico:result.historico,capturas};
}
